fn='''def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    out = [row[:] for row in grid]
    rows = {r for r in range(h) if (r, 0) in marks and (r, w - 1) in marks}
    cols = {c for c in range(w) if (0, c) in marks and (h - 1, c) in marks}
    for r in rows:
        out[r] = [1] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out
'''
